import{_ as a,o as s,c as i,ag as t}from"./chunks/framework.DXGyWiRo.js";const g=JSON.parse('{"title":"远程配置文件","description":"","frontmatter":{},"headers":[],"relativePath":"zh/settings/remote-config.md","filePath":"zh/settings/remote-config.md","lastUpdated":1786673734000}'),o={name:"zh/settings/remote-config.md"};function n(p,e,l,c,r,d){return s(),i("div",null,[...e[0]||(e[0]=[t(`<h1 id="远程配置文件" tabindex="-1">远程配置文件 <a class="header-anchor" href="#远程配置文件" aria-label="Permalink to &quot;远程配置文件&quot;">​</a></h1><p>EasyYapi 支持从远程 URL 加载配置文件，方便团队共享配置。</p><h2 id="配置方法" tabindex="-1">配置方法 <a class="header-anchor" href="#配置方法" aria-label="Permalink to &quot;配置方法&quot;">​</a></h2><p>远程配置 URL 在 IDE 设置中配置，<strong>而非</strong>通过配置文件中的键。</p><p>打开 <strong>Settings → EasyApi → Rules → Remote</strong> 子标签页，每行添加一个 URL：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>http://your-config-server.com/easy-api.config</span></span></code></pre></div><ul><li>每行是一个返回规则/配置内容的远程 URL。</li><li>在 URL 前加 <code>!</code> 可禁用该 URL 而无需删除（例如 <code>!http://config-server.com/legacy.config</code>）。</li><li>空行和空白字符会被忽略。</li></ul><h2 id="从配置文件中引入远程-url" tabindex="-1">从配置文件中引入远程 URL <a class="header-anchor" href="#从配置文件中引入远程-url" aria-label="Permalink to &quot;从配置文件中引入远程 URL&quot;">​</a></h2><p>你也可以在规则文件中使用 <code>###include</code> 指令拉取远程配置：</p><div class="language-properties vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">properties</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">###include https://raw.githubusercontent.com/org/repo/main/easyapi/common.rules</span></span></code></pre></div><p>详见 <a href="./local-file-config#包含其他配置文件">本地配置文件 → 包含其他配置文件</a> 了解 <code>###include</code> 及旧版 <code>properties.additional</code> 形式的完整说明。</p><h2 id="特性" tabindex="-1">特性 <a class="header-anchor" href="#特性" aria-label="Permalink to &quot;特性&quot;">​</a></h2><ul><li>远程配置优先级高于扩展规则和全局规则，但工程规则（<code>.easyapi/</code> / 工程根目录下的 <code>.easy.api.config*</code>）优先级更高</li><li>支持多个远程 URL（在设置界面中每行一个）</li><li>支持自动刷新</li></ul><h2 id="示例" tabindex="-1">示例 <a class="header-anchor" href="#示例" aria-label="Permalink to &quot;示例&quot;">​</a></h2><p>Settings → EasyApi → Rules → Remote：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>http://config-server.com/common.easy.api.config</span></span>
<span class="line"><span>http://config-server.com/project-specific.easy.api.config</span></span></code></pre></div><p>本地配置（优先级低于远程）：</p><div class="language-properties vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">properties</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">field.mock</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=@mock</span></span></code></pre></div>`,18)])])}const u=a(o,[["render",n]]);export{g as __pageData,u as default};
